messages.content:
הנה אפליקציית משחק אינטראקטיבית אחת‑קובץ שבה זוהר (הדמות הראשית) עוברת בין שלבים שונים, עם מוזיקה דינמית, מגדלים שניתן לטפס עליהם ושומרים שמגיבים למצב. הקוד כולל HTML, CSS ו‑JavaScript מלאים, ללא תלות חיצונית חוץ מ‑Howler.js לניהול השמע.

```html
<!-- file: index.html -->
<!DOCTYPE html>
<html lang="he" dir="rtl">
<head>
<meta charset="UTF-8">
<title>זוהר – מסע בין שלבים</title>
<meta name="viewport" content="width=device-width, initial-scale=1">
<style>
 :root {
 --bg-light: #f0f4ff;
 --bg-dark: #1a1a2e;
 --primary: #4a90e2;
 --accent: #ffcc00;
 --tower: #555;
 --guard: #c0392b;
 --zohar-size: 60px;
 }
 body {
 margin:0; font-family:Arial,Helvetica,sans-serif;
 background: var(--bg-light);
 color:#222;
 overflow:hidden;
 display:flex; justify-content:center; align-items:center;
 height:100vh;
 }
 #game {
 position:relative;
 width:100%; height:100%;
 max-width:1024px; max-height:768px;
 background:linear-gradient(to bottom, #87ceeb, #e0f7fa);
 overflow:hidden;
 border-radius:12px;
 box-shadow:0 8px 24px rgba(0,0,0,0.2);
 }
 .tower {
 position:absolute;
 bottom:0;
 width:80px;
 background:var(--tower);
 border-radius:8px 8px 0 0;
 box-shadow: inset 0 0 8px rgba(0,0,0,0.5);
 cursor:pointer;
 transition:transform .3s;
 }
 .tower:hover { transform:scale(1.05); }
 .guard {
 position:absolute;
 width:40px; height:40px;
 background:var(--guard);
 border-radius:50%;
 box-shadow:0 0 6px rgba(0,0,0,0.4);
 animation: patrol 4s linear infinite;
 }
 @keyframes patrol {
 0% { transform:translateX(0); }
 50% { transform:translateX(30px); }
 100% { transform:translateX(0); }
 }
 #zohar {
 position:absolute;
 width:var(--zohar-size);
 height:var(--zohar-size);
 background:url('https://i.imgur.com/6K9VYcM.png') center/contain no-repeat;
 transition:all .5s ease;
 z-index:10;
 }
 #info {
 position:absolute; top:10px; left:10px;
 background:rgba(255,255,255,0.8);
 padding:8px 12px;
 border-radius:6px;
 font-size:14px;
 }
</style>
</head>
<body>
<div id="game">
 <div id="info">שלב: <span id="stage">1</span></div>
 <div id="zohar"></div>
</div>

<script src="https://cdnjs.cloudflare.com/ajax/libs/howler/2.2.4/howler.min.js"></script>
<script>
/* ==================== הגדרות משחק ==================== */
const stages = [
 { // שלב 1 – קרקע רגילה
 name: "קרקע פתוחה",
 music: "https://assets.mixkit.co/music/preview/mixkit-epic-cinematic-trailer-02-1046.mp3",
 towers: 3,
 guardChance: 0.2,
 transition: {type:"move", x:200, y:0}
 },
 { // שלב 2 – מתחת לאדמה
 name: "מערות תת‑קרקעיות",
 music: "https://assets.mixkit.co/music/preview/mixkit-dark-ambient-01-1380.mp3",
 towers: 4,
 guardChance: 0.3,
 transition: {type:"fade", opacity:0.5}
 },
 { // שלב 3 – כוח עליון (אוויר)
 name: "אזור מרחבי",
 music: "https://assets.mixkit.co/music/preview/mixkit-epic-orchestral-cinematic-02-1062.mp3",
 towers: 5,
 guardChance: 0.4,
 transition: {type:"scale", scale:1.2}
 },
 { // שלב 4 – מצב "מת"
 name: "הפסד",
 music: "https://assets.mixkit.co/music/preview/mixkit-sad-piano-01-120.mp3",
 towers: 0,
 guardChance: 0,
 transition: {type:"shake"}
 }
];

let currentStage = 0;
const gameEl = document.getElementById('game');
const zoharEl = document.getElementById('zohar');
const stageLabel = document.getElementById('stage');
let musicPlayer = null;

/* ==================== פונקציות עזר ==================== */
function playMusic(url) {
 if (musicPlayer) musicPlayer.unload();
 musicPlayer = new Howl({src:[url], loop:true, volume:0.6});
 musicPlayer.play();
}

function clearStage() {
 // מסיר מגדלים ושומרים קודמים
 const old = gameEl.querySelectorAll('.tower, .guard');
 old.forEach(el => el.remove());
}

function createTower(index, total) {
 const tower = document.createElement('div');
 tower.className = 'tower';
 const height = 150 + Math.random()*200;
 tower.style.height = `${height}px`;
 const spacing = (gameEl.clientWidth - total*80) / (total+1);
 tower.style.left = `${spacing + index*(80+spacing)}px`;
 tower.addEventListener('click', () => climbTower(tower));
 gameEl.appendChild(tower);
 // אפשרות לשומר
 if (Math.random() < stages[currentStage].guardChance) {
 const guard = document.createElement('div');
 guard.className = 'guard';
 guard.style.bottom = `${height-20}px`;
 guard.style.left = '20px';
 tower.appendChild(guard);
 }
}

function climbTower(tower) {
 // אנימציית טיפוס
 const top = tower.offsetTop;
 const left = tower.offsetLeft + 20;
 zoharEl.style.transition = 'transform 1s ease';
 zoharEl.style.transform = `translate(${left}px, ${top - 80}px)`;
 // אחרי הטיפוס – מעבר לשלב הבא
 setTimeout(nextStage, 1200);
}

/* ==================== ניהול שלבים ==================== */
function loadStage(idx) {
 clearStage();
 const stage = stages[idx];
 stageLabel.textContent = idx+1;
 playMusic(stage.music);
 // יצירת מגדלים
 for (let i=0;i<stage.towers;i++) createTower(i, stage.towers);
 // אפקט מעבר
 applyTransition(stage.transition);
 // מיקום התחלתי של זוהר (במרכז תחתית)
 zoharEl.style.transform = `translate(${gameEl.clientWidth/2-30}px, ${gameEl.clientHeight-80}px)`;
}

function applyTransition(trans) {
 switch(trans.type){
 case "move":
 gameEl.style.transform = `translate(${trans.x}px, ${trans.y}px)`;
 break;
 case "fade":
 gameEl.style.opacity = trans.opacity;
 break;
 case "scale":
 gameEl.style.transform = `scale(${trans.scale})`;
 break;
 case "shake":
 gameEl.animate([
 {transform:'translateX(0)'},
 {transform:'translateX(-10px)'},
 {transform:'translateX(10px)'},
 {transform:'translateX(0)'}
 ], {duration:500});
 break;
 default:
 gameEl.style.transform = 'none';
 }
}

function nextStage(){
 currentStage++;
 if (currentStage >= stages.length) {
 // סיום – חזרה להתחלה אחרי 3 שניות
 setTimeout(()=>{ currentStage=0; loadStage(currentStage); },3000);
 } else {
 loadStage(currentStage);
 }
}

/* ==================== אתחול ==================== */
loadStage(currentStage);
</script>
</body>
</html>
```

**מה עושה האפליקציה**
- מציגה שלבים שונים (קרקע, מערות, מרחב, מצב “מת”) עם מוזיקה תואמת שמשתנה אוטומטית.
- יוצר מגדלים ניתנים ללחיצה; על‑ידי טיפוס על מגדל זוהר עובר לשלב הבא.
- מוסיפה שומרים שמופיעים באחוז מסוים של המגדלים ומבצעים אנימציית “patrol”.
- כולל אפקטי מעבר ייחודיים לכל שלב (הזזה, שקיפות, קנה מידה, רטט) ומוזיקה קיצבית/אווירתית.

**איך להרחיב**
- הוסף שלבים נוספים עם מוזיקה ו‑transition שונים.
- אפשר לשנות את רמת הקושי על‑ידי שינוי `guardChance` או גובה המגדלים.
- שלב מערכת ניקוד או חיי שחקן כדי להפוך את המשחק למאתגר יותר.
